su_kien.raw:
{
  "title": "Tính diện tích elip giao của mặt phẳng và hình trụ",
  "description": "Chương trình này dựng hình trụ và mặt phẳng cắt, sau đó tính diện tích của elip giao tuyến.",
  "memory_declarations": [
    {
      "name": "O",
      "type": "point3",
      "initial_value": [0, 0, 0],
      "source_fact_id": "tam_day_duoi",
      "model_assumption": "Đặt tâm đáy dưới tại gốc tọa độ O(0,0,0)."
    },
    {
      "name": "O_prime",
      "type": "point3",
      "initial_value": [0, 0, 20],
      "source_fact_id": "tam_day_tren",
      "model_assumption": "Đặt tâm đáy trên tại O'(0,0,20) theo đề bài."
    },
    {
      "name": "P_rim",
      "type": "point3",
      "initial_value": [4, 0, 0],
      "model_assumption": "Chọn một điểm trên vành đáy dưới để xác định bán kính, tại (4,0,0) vì bán kính đáy bằng 4."
    },
    {
      "name": "hinh_tru",
      "type": "curved_solid",
      "source_fact_id": "hinh_tru_tron_xoay"
    },
    {
      "name": "alpha",
      "type": "plane3",
      "source_fact_id": "mat_phang_alpha"
    },
    {
      "name": "E",
      "type": "ellipse3",
      "source_fact_id": "cat_hinh_tru_theo_elip"
    },
    {
      "name": "dien_tich_e",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "O",
      "at": [0, 0, 0],
      "source_fact_id": "tam_day_duoi",
      "label": "Tâm đáy dưới O"
    },
    {
      "kind": "declare_point",
      "target_var": "O_prime",
      "at": [0, 0, 20],
      "source_fact_id": "tam_day_tren",
      "label": "Tâm đáy trên O'"
    },
    {
      "kind": "declare_point",
      "target_var": "P_rim",
      "at": [4, 0, 0],
      "label": "Điểm trên vành đáy dưới"
    },
    {
      "kind": "construct_curved_solid",
      "target_var": "hinh_tru",
      "curved_kind": "cylinder",
      "anchor": "O",
      "apex_or_top": "O_prime",
      "rim_point": "P_rim",
      "label": "Hình trụ tròn xoay"
    },
    {
      "kind": "construct_plane_from_equation",
      "target_var": "alpha",
      "a": 2,
      "b": 0,
      "c": -1,
      "d": 10,
      "label": "Mặt phẳng (α)"
    },
    {
      "kind": "assign",
      "target_var": "E",
      "expr": {
        "kind": "intersect_plane_curved_ellipse",
        "solid": "hinh_tru",
        "plane": "alpha"
      }
    },
    {
      "kind": "assign",
      "target_var": "dien_tich_e",
      "expr": {
        "kind": "measure",
        "quantity": "area",
        "of": "E"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách dựng hình trụ và mặt phẳng cắt xiên, sau đó tính diện tích của elip giao tuyến."
}

